using Brutal;
using Brutal.Numerics;
using Brutal.TextureApi;
using Brutal.TextureApi.Abstractions;

public static class TextureProbe
{
    // Compile-only. None of these methods are invoked.
    public static byte[] DecodePng(ReadOnlySpan<byte> encoded)
    {
        ITexture texture = TextureLoader.LoadFromMemory(encoded, TextureLoader.FormatType.Png,
            Brutal.TextureApi.Stb.Loader.LoadSettings.ForceRgba8);
        using var lifetime = texture.Using();
        TexelCount3 extent = texture.Extent;
        TextureFormat format = texture.Format;
        ByteSize pitch = texture.RowPitch(0);
        var layout = new TextureMemoryLayout(texture);
        TextureImageMemoryLayout first = layout.ImageLayout(0);
        StageUploadRegions upload = UploadRegions.Build(texture);
        foreach (StagingRegion range in upload.StageBufferRegions)
        {
            ByteSize start = range.SourceStartOffset;
            ByteSize destination = range.DestinationOffset;
            ByteSize length = range.SizeInBytes;
        }
        foreach (UploadRegion copy in upload.CopyToImageRegions)
        {
            int baseMip = copy.BaseLevel, layer = copy.BaseLayer, layers = copy.LayerCount;
            ByteSize offset = copy.BufferOffset;
        }
        return texture.ImageData(0, 0, 0).ToArray();
    }
    public readonly record struct QuadVertex(float2 Position, float2 Uv, float4 Color);
    public static void Quad(Brutal.Collections.NativeStrideList vertices, Brutal.Collections.NativeStrideList indices,
        QuadVertex a, QuadVertex b, QuadVertex c, QuadVertex d)
        => Brutal.Render.Mesh.ProcGenMeshLibrary.AddQuad<QuadVertex>(vertices, indices, a, b, c, d);

    public static void OwnFontCoverage(int width, int height, ReadOnlySpan<byte> rgba)
    {
        GenericTexture texture = GenericTexture.Defaults.RGBA8UNorm(new int2(width, height));
        try
        {
            rgba.CopyTo(texture.Data);
            StageUploadRegions upload = UploadRegions.Build(texture);
            FormatDescriptor descriptor = texture.Format.Descriptor();
        }
        finally { texture.Destroy(); } // GenericTexture is not TextureLoader.Unload-compatible.
    }
}

using Brutal.VulkanApi;
using Brutal.VulkanApi.Abstractions;

public static unsafe class VulkanProbe
{
    // Compile-only: no device/allocation/descriptor operations are invoked.
    public static void Check(Device device, IImageAllocator allocator, int width, int height, int capacity)
    {
        using var image = allocator.CreateImage(new ImageEx.CreateInfo
        {
            Name = "", ImageType = VkImageType._2D, ImageFormat = VkFormat.R8G8B8A8UNorm,
            ImageExtent = new VkExtent3D { Width = width, Height = height, Depth = 1 },
            ImageMipLevels = 1, ImageArrayLayers = 1, ImageSamples = VkSampleCountFlags._1Bit,
            ImageTiling = VkImageTiling.Optimal,
            ImageUsage = VkImageUsageFlags.TransferDstBit | VkImageUsageFlags.SampledBit,
            ImageSharingMode = VkSharingMode.Exclusive, AllocPreference = MemoryPreference.PreferGpu
        });
        using var view = image.CreateImageView(VkImageViewType._2D, image.GetFullRange(VkImageAspectFlags.ColorBit), null);
        using var layout = device.CreateDescriptorSetLayout(new DescriptorSetLayoutEx.CreateInfo
        {
            Bindings = new[] { new VkDescriptorSetLayoutBinding
            {
                Binding = 0, DescriptorType = VkDescriptorType.CombinedImageSampler,
                DescriptorCount = 1, StageFlags = VkShaderStageFlags.FragmentBit
            }}
        }, null);
        using var pool = device.CreateDescriptorPool(new DescriptorPoolEx.CreateInfo
        {
            MaxSets = capacity, Flags = VkDescriptorPoolCreateFlags.FreeDescriptorSetBit,
            PoolSizes = new[] { new VkDescriptorPoolSize { Type = VkDescriptorType.CombinedImageSampler, DescriptorCount = capacity } }
        }, null);
        var set = device.AllocateDescriptorSet(pool, layout);
        device.FreeDescriptorSet(pool, set);
    }
}
